#[test]
fn open_makes_a_close_on_exec_terminal_of_the_requested_size() {
    let pair = open(100, 30).unwrap();
    for fd in [&pair.master, &pair.slave] {
        // SAFETY: F_GETFD only reads the descriptor's flags.
        let flags = unsafe { libc::fcntl(fd.as_raw_fd(), libc::F_GETFD) };
        assert!(
            flags != -1 && flags & libc::FD_CLOEXEC != 0,
            "{fd:?} is not close-on-exec"
        );
    }
    // SAFETY: isatty only inspects the descriptor.
    assert_eq!(unsafe { libc::isatty(pair.slave.as_raw_fd()) }, 1);
    assert_eq!(size(pair.slave.as_fd()), (100, 30));
    // Typed on the master, a line on the slave; the master then reads the terminal's echo of it and what the slave
    // wrote, as a terminal shows them (`\n` becomes `\r\n`).
    write_all(pair.master.as_fd(), b"ping\n");
    read_exactly(pair.slave.as_fd(), b"ping\n");
    write_all(pair.slave.as_fd(), b"pong\n");
    read_exactly(pair.master.as_fd(), b"ping\r\npong\r\n");
}

#[test]
fn resize_sets_the_size_the_terminal_reports() {
    let pair = open(80, 24).unwrap();
    resize(pair.master.as_fd(), 120, 40).unwrap();
    assert_eq!(size(pair.slave.as_fd()), (120, 40));
    resize(pair.master.as_fd(), 1, 32767).unwrap();
    assert_eq!(size(pair.slave.as_fd()), (1, 32767));
}

#[test]
fn ctrl_c_on_the_terminal_interrupts_the_session_that_took_it() {
    let pair = open(80, 24).unwrap();
    let pid = session_child(&pair.slave, true);
    read_exactly(pair.master.as_fd(), b"READY\r\n");
    write_all(pair.master.as_fd(), b"\x03x\n");
    let st = status(pid, pair.master.as_fd());
    assert!(
        libc::WIFSIGNALED(st) && libc::WTERMSIG(st) == libc::SIGINT,
        "not interrupted by SIGINT: wait status {st:#x} (exit code {})",
        libc::WEXITSTATUS(st)
    );
}

#[test]
fn control_without_make_controlling_ctrl_c_interrupts_nothing() {
    let pair = open(80, 24).unwrap();
    let pid = session_child(&pair.slave, false);
    read_exactly(pair.master.as_fd(), b"READY\r\n");
    write_all(pair.master.as_fd(), b"\x03x\n");
    let st = status(pid, pair.master.as_fd());
    assert!(
        libc::WIFEXITED(st) && libc::WEXITSTATUS(st) == 0,
        "the control read past the \\x03 and exited 0; wait status {st:#x}"
    );

#[test]
fn make_controlling_outside_a_new_session_returns_the_errno() {
    let pair = open(80, 24).unwrap();
    let slave = pair.slave.as_raw_fd();
    // SAFETY: the closure makes async-signal-safe calls only (`make_controlling` reads errno without allocating).
    let pid = unsafe {
        fork(move || match make_controlling(slave) {
            Err(libc::EPERM) => 0,
            Err(_) => 1,
            Ok(()) => 2,
        })
    };
    let st = status(pid, pair.master.as_fd());
    assert!(
        libc::WIFEXITED(st) && libc::WEXITSTATUS(st) == 0,
        "want Err(EPERM) from a process that is not a session leader; wait status {st:#x}"
    );

pub(crate) fn create(cols: u16, rows: u16) -> io::Result<(ConPty, ConPtyEnds)> {
    let size = coord(cols, rows)?;
    // Step 1: from here on, every early return drops `hang_up`, and the closer exits without a close.
    let (hang_up, hung_up) = mpsc::channel::<HPCON>();
    std::thread::Builder::new()
        .name("conpty-close".into())
        .stack_size(STACK)
        .spawn(move || {
            // The pseudoconsole, if `create` made one; then wait until the `ConPty` is gone (its sender with it).
            if let Ok(hpc) = hung_up.recv() {
                let _ = hung_up.recv();
                // SAFETY: the pseudoconsole `create` made, closed only here, once; nothing uses it any more.
                unsafe { ClosePseudoConsole(hpc) };
            }
        })?;
    // Step 2.
    let (pty_input, input) = pipe()?;
    let (output, pty_output) = pipe()?;
    let mut hpc: HPCON = 0;
    // SAFETY: two valid pipe ends and a valid out pointer; flags 0 (step 3).
    let hr = unsafe { CreatePseudoConsole(size, pty_input.as_raw_handle(), pty_output.as_raw_handle(), 0, &mut hpc) };
    // Step 4, on every path.
    drop((pty_input, pty_output));
    check(hr)?;
    // Cannot fail: the closer keeps its receiver until it has received this. Were it gone, the pseudoconsole
    // would stay open (never a close here, on the caller's thread).
    let _ = hang_up.send(hpc);
    let pty = ConPty { hpc, _hang_up: hang_up };
    Ok((pty, ConPtyEnds { output, input }))

/// `ResizePseudoConsole`.
pub(crate) fn resize(&self, cols: u16, rows: u16) -> io::Result<()> {
    let size = coord(cols, rows)?;
    // SAFETY: a live pseudoconsole: it is closed only after `self` is gone.
    check(unsafe { ResizePseudoConsole(self.hpc, size) })
}

/// Closes on a worker thread; the caller enforces `deadline` independently (the close can block).
pub(crate) fn close(self, deadline: Instant) {
    // Dropping `self` wakes the closer (step 7). Nothing here waits, so the deadline stays the caller's (step 8).
    let _ = deadline;
    drop(self);
}

/// A size conhost takes: 1..=32767 cells each way.
fn coord(cols: u16, rows: u16) -> io::Result<COORD> {
    match (i16::try_from(cols), i16::try_from(rows)) {
        (Ok(x @ 1..), Ok(y @ 1..)) => Ok(COORD { X: x, Y: y }),
        _ => Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("terminal size {cols}x{rows} is outside 1..=32767 cells each way"),
        )),
    }
}

/// An `HRESULT` as a result; a wrapped Win32 error (`HRESULT_FROM_WIN32`) comes back as that error's code.
fn check(hr: i32) -> io::Result<()> {
    if hr >= 0 {
        return Ok(());
    }
    let hr = hr as u32;
    let code = if hr >> 16 == 0x8007 { hr & 0xFFFF } else { hr };
    Err(io::Error::from_raw_os_error(code as i32))

pub(super) fn start(args: &Args) -> io::Result<Supervisor> {
    own_console();
    let name = args.pipe.as_deref().ok_or_else(|| io::Error::other("missing --pipe"))?;
    // SAFETY: a plain open by pid, not inheritable; checked for null.
    let host = unsafe { OpenProcess(PROCESS_SYNCHRONIZE, FALSE, args.host_pid) };
    // SAFETY: `host` is null or a fresh handle owned by nobody else.
    let host = OwnedHandle::try_from(unsafe { HandleOrNull::from_raw_handle(host) })
        .map_err(|_| io::Error::last_os_error())?;
    let inbox = Arc::new(Inbox::default());
    let out = Arc::new(Outbox::default());
    // Armed before the channel exists, so it is armed before Ready.
    watch(host, &inbox, |_| Event::HostGone)?;
    let members = Members::start(&inbox)?;
    let diag = Arc::new(Diag::default());
    diag.start(io::stderr())?;
    // The pipe's server must be the host: the handle above then names the live host, not a reused pid.
    let pipe = channel::connect(name, args.host_pid)?;
    channel::start(&pipe, &inbox, &out)?;
    let sup = Supervisor::new(inbox, out, members, diag, pipe.as_raw_handle() as usize);
    sup.send(&Msg::Ready {
        version: VERSION,
        pid: std::process::id(),
        info: INFO_PIDFD_HOST, // the host is watched through its process handle
    });
    Ok(sup)

/// The supervisor runs on its own console (the host starts it with `CREATE_NO_WINDOW`), so its
/// CTRL_BREAKs never reach the host and nothing here changes the host's console state. Children inherit
/// the ignore-Ctrl+C flag from their creator, so it is cleared here (a terminal child must be
/// interruptible); the supervisor itself ignores every console event.
fn own_console() {
    unsafe extern "system" fn ignore(_event: u32) -> i32 {
        TRUE
    }
    // SAFETY: changes only this process's handler list; `ignore` lives as long as the process.
    unsafe {
        SetConsoleCtrlHandler(None, FALSE);
        SetConsoleCtrlHandler(Some(ignore), TRUE);
    }

/// Waits for `handle` on a helper thread, then queues `event(&handle)`.
pub(super) fn watch(
    handle: OwnedHandle,
    inbox: &Arc<Inbox>,
    event: impl FnOnce(&OwnedHandle) -> Event + Send + 'static,
) -> io::Result<()> {
    let inbox = inbox.clone();
    channel::helper("watch", move || {
        // SAFETY: a valid process handle owned by this thread.
        unsafe { WaitForSingleObject(handle.as_raw_handle(), INFINITE) };
        inbox.event(event(&handle));
    })

/// Opens the host's pipe and checks that its server is the host (`--host-pid`).
pub(super) fn connect(name: &str, host_pid: u32) -> io::Result<Arc<OwnedHandle>> {
    let wide: Vec<u16> = name.encode_utf16().chain([0]).collect();
    // SAFETY: a NUL-terminated name; null security attributes (not inheritable). SQOS identification only:
    // whoever serves the pipe cannot impersonate the supervisor.
    let h = unsafe {
        CreateFileW(
            wide.as_ptr(),
            GENERIC_READ | GENERIC_WRITE,
            0,
            std::ptr::null(),
            OPEN_EXISTING,
            FILE_FLAG_OVERLAPPED | SECURITY_SQOS_PRESENT | SECURITY_IDENTIFICATION,
            std::ptr::null_mut(),
        )
    };
    // SAFETY: `h` is INVALID_HANDLE_VALUE or a fresh handle owned by nobody else.
    let pipe = OwnedHandle::try_from(unsafe { HandleOrInvalid::from_raw_handle(h) })
        .map_err(|_| io::Error::last_os_error())?;
    let mut server = 0;
    // SAFETY: a valid pipe handle and a valid out pointer.
    if unsafe { GetNamedPipeServerProcessId(pipe.as_raw_handle(), &mut server) } == 0 {
        return Err(io::Error::last_os_error());
    }
    if server != host_pid {
        return Err(io::Error::other(format!(
            "the pipe is served by pid {server}, not the host {host_pid}"
        )));
    }
    Ok(Arc::new(pipe))

fn read_requests(io: &Overlapped, inbox: &Inbox) {
    let (mut buf, mut start, mut chunk) = (Vec::new(), 0, vec![0u8; 64 * 1024]);
    loop {
        match omni_proto::decode(buf.get(start..).unwrap_or_default()) {
            Ok(Some((msg, used))) => {
                start += used;
                let request = matches!(
                    msg,
                    Msg::Spawn(_)
                        | Msg::Go { .. }
                        | Msg::Stop { .. }
                        | Msg::Resize { .. }
                        | Msg::List { .. }
                        | Msg::Release { .. }
                );
                // A supervisor-bound kind from the host is malformed: the host is gone.
                if !request || !inbox.request(msg) {
                    break;
                }
            }
            Ok(None) => {
                buf.drain(..start);
                start = 0;
                match io.read(&mut chunk) {
                    Ok(n) => buf.extend_from_slice(chunk.get(..n).unwrap_or_default()),
                    Err(_) => break,
                }
            }
            Err(_) => break,
        }
    }
    inbox.event(Event::HostGone);

fn write_replies(io: &Overlapped, out: &Outbox, inbox: &Inbox) {
    while let Some(frames) = out.take() {
        let mut rest = frames.as_slice();
        while !rest.is_empty() {
            match io.write(rest) {
                Ok(n) if n > 0 => rest = rest.get(n..).unwrap_or_default(),
                _ => {
                    out.close();
                    inbox.event(Event::HostGone);
                    return;
                }
            }
        }
        out.written();
        inbox.progress();
    }

/// Waits for the operation `ov` started; a message-mode partial read (`ERROR_MORE_DATA`) is data.
fn finish(&self, ok: i32, ov: &OVERLAPPED) -> io::Result<usize> {
    let more = |e: &io::Error| e.raw_os_error() == Some(ERROR_MORE_DATA as i32);
    if ok == 0 {
        let e = io::Error::last_os_error();
        if e.raw_os_error() != Some(ERROR_IO_PENDING as i32) && !more(&e) {
            return Err(e); // nothing was queued
        }
    }
    let mut n = 0;
    // SAFETY: `ov` belongs to an operation queued on this pipe; waiting completes it before `ov` is dropped.
    if unsafe { GetOverlappedResult(self.pipe.as_raw_handle(), ov, &mut n, TRUE) } == 0 {
        let e = io::Error::last_os_error();
        if !more(&e) {
            return Err(e);
        }
    }
    Ok(n as usize)

/// `"argv0" args...`, recoverable by the MSVC rules (`CommandLineToArgvW`, Rust's `args_os`).
pub(super) fn exe(argv0: &[u16], args: &[Vec<u16>]) -> Result<Vec<u16>, &'static str> {
    if argv0.contains(&QUOTE) {
        return Err("argv[0] contains a double quote");
    }
    let mut cmd = vec![QUOTE];
    cmd.extend_from_slice(argv0);
    cmd.push(QUOTE);
    for arg in args {
        cmd.push(SPACE);
        append_arg(&mut cmd, arg);
    }
    Ok(cmd)
}

/// `"argv0" tail` (amendment WP8b): the same quoted `argv[0]` as `exe`, then the caller's tail exactly as given (std's
/// `CommandExt::raw_arg`). An empty tail adds nothing, not even the space.
pub(super) fn verbatim(argv0: &[u16], tail: &[u16]) -> Result<Vec<u16>, &'static str> {
    let mut cmd = exe(argv0, &[])?;
    if !tail.is_empty() {
        cmd.push(SPACE);
        cmd.extend_from_slice(tail);
    }
    Ok(cmd)

/// `cmd.exe /e:ON /v:OFF /d /c ""script" args..."` (std `make_bat_command_line`). Arguments that cannot be
/// passed literally to a batch file (`\r`, `\n`) are refused, as std does.
pub(super) fn bat(script: &[u16], args: &[Vec<u16>]) -> Result<Vec<u16>, &'static str> {
    if script.contains(&QUOTE) || script.last() == Some(&BACKSLASH) {
        return Err("a batch file path may not contain `\"` or end with `\\`");
    }
    if script.contains(&PERCENT) {
        return Err("a batch file whose path contains `%` cannot be run safely");
    }
    let mut cmd: Vec<u16> = "cmd.exe /e:ON /v:OFF /d /c \"".encode_utf16().collect();
    cmd.push(QUOTE);
    cmd.extend_from_slice(script);
    cmd.push(QUOTE);
    for arg in args {
        cmd.push(SPACE);
        if arg.iter().any(|&c| c == CR || c == LF) {
            return Err("a batch file argument cannot contain a line break");
        }
        append_bat_arg(&mut cmd, arg);
    }
    cmd.push(QUOTE);
    Ok(cmd)

/// std's `to_user_path` / `from_wide_to_user_path` (same commit, `library/std/src/sys/args/windows.rs`):
/// cmd.exe cannot open a verbatim path, so `\\?\C:\…` becomes `C:\…` and `\\?\UNC\srv\…` becomes `\\srv\…`, but
/// only when the plain spelling names the same file (`GetFullPathNameW` gives it back unchanged) and is short
/// enough (under 260 units, with the NUL). Where std would keep the verbatim spelling (which cmd.exe cannot
/// run), this refuses. A path without the `\\?\` prefix is returned as it is.
pub(super) fn user_path(path: &[u16]) -> Result<Vec<u16>, &'static str> {
    const REFUSED: &str = "a verbatim (\\\\?\\) batch file path has no plain spelling of the same file that \
                           cmd.exe can run (too long, not a drive or UNC path, or it would be normalized)";
    const QUERY: u16 = b'?' as u16;
    const COLON: u16 = b':' as u16;
    const U: u16 = b'U' as u16;
    const N: u16 = b'N' as u16;
    const C: u16 = b'C' as u16;
    let [BACKSLASH, BACKSLASH, QUERY, BACKSLASH, rest @ ..] = path else {
        return Ok(path.to_vec());
    };
    let plain: Vec<u16> = match rest {
        [U, N, C, BACKSLASH, tail @ ..] => [BACKSLASH, BACKSLASH].iter().chain(tail).copied().collect(),
        [_, COLON, BACKSLASH, ..] => rest.to_vec(),
        _ => return Err(REFUSED),
    };
    if path.len() + 1 > 260 {
        return Err(REFUSED);
    }
    let full = std::path::absolute(Path::new(&OsString::from_wide(&plain))).map_err(|_| REFUSED)?;
    if full.as_os_str().encode_wide().eq(plain.iter().copied()) {
        Ok(plain)
    } else {
        Err(REFUSED)
    }

/// A protocol OS string (WTF-8, `docs/protocol.md`) as UTF-16. `None` when it is malformed or holds a NUL.
pub(super) fn wide(bytes: &[u8]) -> Option<Vec<u16>> {
    fn cont(bytes: &[u8], i: usize) -> Option<u32> {
        bytes
            .get(i)
            .filter(|&&b| b & 0xC0 == 0x80)
            .map(|&b| u32::from(b & 0x3F))
    }
    let mut out = Vec::with_capacity(bytes.len());
    let mut i = 0;
    while let Some(&b0) = bytes.get(i) {
        let b = u32::from(b0);
        let (cp, len) = match b0 {
            0 => return None,
            0x01..=0x7F => (b, 1),
            0xC2..=0xDF => ((b & 0x1F) << 6 | cont(bytes, i + 1)?, 2),
            // Generalized UTF-8: surrogate code points (ED A0..BF) are WTF-8.
            0xE0..=0xEF => ((b & 0x0F) << 12 | cont(bytes, i + 1)? << 6 | cont(bytes, i + 2)?, 3),
            0xF0..=0xF4 => {
                let cp = (b & 0x07) << 18 | cont(bytes, i + 1)? << 12 | cont(bytes, i + 2)? << 6 | cont(bytes, i + 3)?;
                (cp, 4)
            }
            _ => return None,
        };
        // Overlong forms and code points above U+10FFFF are malformed.
        let shortest = match len {
            1 => 0,
            2 => 0x80,
            3 => 0x800,
            _ => 0x1_0000,
        };
        if cp < shortest || cp > 0x10_FFFF {
            return None;
        }
        match u16::try_from(cp) {
            Ok(unit) => out.push(unit),
            Err(_) => {
                let c = cp - 0x1_0000;
                out.extend([0xD800 | (c >> 10) as u16, 0xDC00 | (c & 0x3FF) as u16]);
            }
        }
        i += len;
    }
    Some(out)

/// What one grant gives the profile on one path.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(super) enum Grant {
    /// Read and execute, inherited by the subtree.
    Read,
    /// Read, write, execute and delete, inherited. Never `FILE_DELETE_CHILD`.
    Write,
}

impl Grant {
    fn mask(self) -> u32 {
        match self {
            Grant::Read => FILE_GENERIC_READ | FILE_GENERIC_EXECUTE,
            Grant::Write => FILE_GENERIC_READ | FILE_GENERIC_WRITE | FILE_GENERIC_EXECUTE | DELETE,
        }

/// Adds the grant unless `path` already carries it as an explicit ACE.
pub(super) fn apply(path: &Path, sid: &Sid, grant: Grant) -> io::Result<()> {
    // A directory's grant covers its subtree; a file takes no inheritance flags.
    let flags = if std::fs::metadata(path)?.is_dir() {
        OBJECT_INHERIT_ACE | CONTAINER_INHERIT_ACE
    } else {
        0
    };
    let current = Dacl::read(path)?;
    if current.has(sid, grant.mask(), flags)? {
        return Ok(());
    }
    current.write(path, sid, GRANT_ACCESS, grant.mask(), flags)
}

/// Removes every explicit ACE for the SID from `path` (and, with them, their inherited copies below it).
pub(super) fn revoke(path: &Path, sid: &Sid) -> io::Result<()> {
    let current = Dacl::read(path)?;
    if !current.mentions(sid)? {
        return Ok(());
    }
    current.write(path, sid, REVOKE_ACCESS, 0, 0)

/// Makes the profile read-only on the link at `path`: a deny ACE below an inherited allow does not hold, so instead
/// the DACL is detached from inheritance (its effective ACEs copied in place, so every other trustee keeps what it
/// had), every explicit ACE for `sid` is removed, and one read-and-execute ACE is granted. Idempotent and run for
/// every joining profile, so a second container with a write grant that was copied in by the first command's detach is
/// also stripped to read-only. A directory grants it inheritable, and the parent write grant never carries
/// `FILE_DELETE_CHILD`, so the container can neither write into, delete nor rename the path.
pub(super) fn protect(path: &Path, sid: &Sid) -> io::Result<()> {
    let handle = open(path, true)?;
    let flags = if file_info(&handle)?.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY != 0 {
        OBJECT_INHERIT_ACE | CONTAINER_INHERIT_ACE
    } else {
        0
    };
    // Copy the inherited ACEs in place and disable further inheritance, so the parents' write grants stop flowing in.
    let detached = HandleDacl::read(&handle)?;
    detached.set(
        &handle,
        DACL_SECURITY_INFORMATION | PROTECTED_DACL_SECURITY_INFORMATION,
        detached.acl,
    )?;
    // Drop every right any profile had here (the copies of the parents' write grants among them), then read-only.
    let current = HandleDacl::read(&handle)?;
    let entries = [
        explicit(sid, REVOKE_ACCESS, 0, 0),
        explicit(sid, GRANT_ACCESS, Grant::Read.mask(), flags),
    ];
    current.edit(&handle, &entries)

/// Restores a DACL captured by [`capture`] on the link at `path`, including whether it was protected from inheritance.
/// Setting an unprotected DACL drops the inherited ACEs the string carries and lets the parents' ACEs flow back in.
pub(super) fn restore(path: &Path, sddl: &str) -> io::Result<()> {
    let handle = open(path, true)?;
    let text: Vec<u16> = sddl.encode_utf16().chain([0]).collect();
    let mut sd: PSECURITY_DESCRIPTOR = std::ptr::null_mut();
    // SAFETY: a NUL-terminated SDDL string and an out pointer for the descriptor (freed below).
    if unsafe {
        ConvertStringSecurityDescriptorToSecurityDescriptorW(
            text.as_ptr(),
            SDDL_REVISION_1,
            &mut sd,
            std::ptr::null_mut(),
        )
    } == 0
    {
        return Err(io::Error::last_os_error());
    }
    let restore = (|| {
        let (mut control, mut revision): (u16, u32) = (0, 0);
        // SAFETY: a valid descriptor and out values.
        if unsafe { GetSecurityDescriptorControl(sd, &mut control, &mut revision) } == 0 {
            return Err(io::Error::last_os_error());
        }
        let (mut present, mut dacl, mut defaulted): (i32, *mut ACL, i32) = (0, std::ptr::null_mut(), 0);
        // SAFETY: a valid descriptor and out values; `dacl` points into `sd`.
        if unsafe { GetSecurityDescriptorDacl(sd, &mut present, &mut dacl, &mut defaulted) } == 0 {
            return Err(io::Error::last_os_error());
        }
        let info = DACL_SECURITY_INFORMATION
            | if control & SE_DACL_PROTECTED != 0 {
                PROTECTED_DACL_SECURITY_INFORMATION
            } else {
                UNPROTECTED_DACL_SECURITY_INFORMATION
            };
        // SAFETY: a live handle and a DACL that lives in `sd`.
        win32(unsafe {
            SetSecurityInfo(
                handle.as_raw_handle() as HANDLE,
                SE_FILE_OBJECT,
                info,
                std::ptr::null_mut(),
                std::ptr::null_mut(),
                dacl,
                std::ptr::null(),
            )
        })

/// The explicit ACEs naming `sid`, as (denies, mask, flags).
pub(super) fn entries(&self, sid: &Sid) -> io::Result<Vec<(bool, u32, u32)>> {
    if self.acl.is_null() {
        return Ok(Vec::new());
    }
    let mut size = ACL_SIZE_INFORMATION::default();
    // SAFETY: a valid ACL and the structure this information class expects, with its exact size.
    let ok = unsafe {
        GetAclInformation(
            self.acl,
            (&raw mut size).cast(),
            size_of::<ACL_SIZE_INFORMATION>() as u32,
            AclSizeInformation,
        )
    };
    if ok == 0 {
        return Err(io::Error::last_os_error());
    }
    let mut found = Vec::new();
    for index in 0..size.AceCount {
        let mut ace = std::ptr::null_mut();
        // SAFETY: an index below AceCount of a valid ACL.
        if unsafe { GetAce(self.acl, index, &mut ace) } == 0 {
            return Err(io::Error::last_os_error());
        }
        // SAFETY: every ACE starts with an ACE_HEADER.
        let header = unsafe { *ace.cast::<ACE_HEADER>() };
        if !matches!(header.AceType, ACCESS_ALLOWED | ACCESS_DENIED)
            || u32::from(header.AceFlags) & INHERITED_ACE != 0
        {
            continue;
        }
        // Allowed and denied ACEs share this layout: header, mask, then the SID in place.
        let ace = ace.cast::<ACCESS_ALLOWED_ACE>();
        // SAFETY: an allowed/denied ACE, whose SID starts at SidStart.
        let (mask, named) = unsafe { ((*ace).Mask, EqualSid((&raw mut (*ace).SidStart).cast(), sid.raw()) != 0) };
        if named {
            found.push((header.AceType == ACCESS_DENIED, mask, u32::from(header.AceFlags)));
        }
    }
    Ok(found)

pub(super) fn has(&self, sid: &Sid, mask: u32, flags: u32) -> io::Result<bool> {
    Ok(self
        .entries(sid)?
        .iter()
        .any(|&(denies, m, f)| !denies && m & mask == mask && f & flags == flags))
}

pub(super) fn mentions(&self, sid: &Sid) -> io::Result<bool> {
    Ok(!self.entries(sid)?.is_empty())
}

